     1988:    /* We only use 'chromaticities' for RGB to gray */
     1989: #  ifdef PNG_READ_RGB_TO_GRAY_SUPPORTED
     1990:       png_ptr->chromaticities = chromaticities;
     1991: #  endif /* READ_RGB_TO_GRAY */
     1992: 
     1993:    return handled_ok;
     1994:    PNG_UNUSED(length)
     1995: }
     1996: #else
     1997: #  define png_handle_mDCV NULL
     1998: #endif
     1999: 
     2000: #ifdef PNG_READ_eXIf_SUPPORTED
     2001: static png_handle_result_code /* PRIVATE */
     2002: png_handle_eXIf(png_struct *png_ptr, png_info *info_ptr, png_uint_32 length)
     2003: {
     2004:    png_byte *buffer = NULL;
     2005: 
     2006:    png_debug(1, "in png_handle_eXIf");
     2007: 
     2008:    buffer = png_read_buffer(png_ptr, length);
     2009: 
     2010:    if (buffer == NULL)
     2011:    {
     2012:       png_crc_finish(png_ptr, length);
     2013:       png_chunk_benign_error(png_ptr, "out of memory");
     2014:       return handled_error;
     2015:    }
     2016: 
