     2023:     * II, however PNGv3 states that the first 4 bytes should be checked.
     2024:     * The caller ensures that there are four bytes available.
     2025:     */
     2026:    {
>>>  2027:       png_uint_32 header = png_get_uint_32(buffer);
     2028: 
     2029:       /* These numbers are copied from the PNGv3 spec: */
     2030:       if (header != 0x49492A00 && header != 0x4D4D002A)
     2031:       {
     2032:          png_chunk_benign_error(png_ptr, "invalid");
     2033:          return handled_error;
     2034:       }
     2035:    }
